import { Euler, Matrix4, Quaternion, Vector3 } from '../engine/index.js';

const TAU = Math.PI * 2;
const HULL_X = [ .42, .53, .40 ], HULL_Y = [ .52, .62, .42 ], HULL_Z = [ .35, 0, -.32 ];
const clamp = ( v, a = 0, b = 1 ) => Math.max( a, Math.min( b, v ) );
const smooth = ( a, b, dt, speed = 6 ) => a + ( b - a ) * ( 1 - Math.exp( - clamp( dt, 0, 0.06 ) * speed ) );
const wrap = x => Math.atan2( Math.sin( x ), Math.cos( x ) );

// Dense glTF joint hierarchies, not single rigid transformations or shader-only motion.
// across the entire creature. All animation targets are generated by this
// deterministic director. Each bone retains previous-frame rotation and uses
// exponential interpolation, so acquired targets never cause abrupt snapping.
export function skeletonTargets( id, boss, captain, time, attackPulse = 0, lastKind = '', attackMotion = null ) {
	const brain = boss.brain;
	const speed = clamp( brain.currentSpeed / Math.max( boss.chaseSpeed, 1 ) );
	const windup = brain.state === 'windup' ? clamp( 1 - brain.windup / Math.max( brain.attack?.windup || 2, 0.1 ) ) : 0;
	const charge = brain.state === 'charge' ? 1 : 0;
	const bite = brain.attack?.kind === 'triple_bite' || ( lastKind === 'triple_bite' && attackPulse > 0 );
	const grapple = brain.attack?.kind === 'grapple' || ( lastKind === 'grapple' && attackPulse > 0 );
	const relative = Math.hypot( captain.x - brain.x, captain.z - brain.z );
	const angle = wrap( Math.atan2( captain.x - brain.x, captain.z - brain.z ) - brain.heading );
	const attention = clamp( ( 180 - relative ) / 110 ) * ( brain.state === 'return' ? 0 : 1 );
	const poses = {};
	if ( id === 'shark' ) {
		const beat = time * ( 3.2 + 4.1 * speed );
		for ( let k = 0; k < 12; k ++ ) poses[ `SharkSpine${ k }` ] = {
			yaw: Math.sin( beat - k * 0.24 ) * ( 0.026 + speed * 0.032 ) * ( 0.22 + 0.78 * k / 11 ),
			pitch: -windup * 0.006 + Math.sin( time * 1.5 + k * 0.35 ) * 0.009,
		};
		for ( let k = 0; k < 6; k ++ ) poses[ `TailFin${ k }` ] = {
			yaw: Math.sin( beat - k * 0.32 - 2.6 ) * ( 0.055 + speed * 0.08 ),
			roll: Math.cos( beat - k * 0.4 ) * 0.035,
		};
		for ( let k = 0; k < 4; k ++ ) poses[ `SharkJaw${ k }` ] = {
			pitch: ( windup * 0.36 + charge * 0.48 + attackPulse * 0.52 ) * ( 0.5 - k * 0.08 ),
		};
		for ( const [ side, dir ] of [ [ 'Left', -1 ], [ 'Right', 1 ] ] ) {
			for ( let k = 0; k < 8; k ++ ) poses[ `Fin${ side }${ k }` ] = {
				roll: dir * ( 0.016 + charge * 0.029 ) + Math.sin( time * 1.8 + k * 0.3 + dir ) * 0.023,
				pitch: Math.sin( time * 1.2 - k * 0.45 + dir ) * 0.012,
			};
			for ( let k = 0; k < 6; k ++ ) poses[ `Pelvic${ side }${ k }` ] = { roll: dir * 0.014 + Math.sin( beat * 0.55 + k * 0.44 ) * 0.012 };
		}
		for ( let k = 0; k < 6; k ++ ) poses[ `Dorsal${ k }` ] = { roll: Math.sin( beat * 0.36 - k * 0.22 ) * 0.014 };
	} else if ( id === 'turtle' ) {
		for ( const [ side, k ] of [ [ 'L', 0 ], [ 'R', Math.PI * 0.52 ] ] ) {
			for ( const part of [ 'Front', 'Back' ] ) {
				const freq = part === 'Front' ? 1.5 + speed : 1.1 + speed * 0.75;
				for ( let j = 0; j < 10; j ++ ) poses[ `${ part }Fin${ side }${ j }` ] = {
					pitch: Math.sin( time * freq + k - j * 0.2 ) * ( 0.025 + 0.014 * windup ) - windup * 0.022,
					roll: ( side === 'L' ? -1 : 1 ) * ( 0.022 + 0.022 * attackPulse ) * Math.cos( j * 0.12 ),
				};
			}
		}
		for ( let j = 0; j < 9; j ++ ) poses[ `Neck${ j }` ] = {
			yaw: angle * attention * .025 + Math.sin( time * .7 + j * .32 ) * .015,
			pitch: windup * .022 - attackPulse * .028,
		};
		poses.TurtleHead = { pitch: 0.09 * windup - attackPulse * 0.21, yaw: angle * attention * 0.12 };
		for ( let j = 0; j < 10; j ++ ) poses[ `Shell${ j }` ] = { pitch: .0018 * Math.sin( time * .9 + j * .17 ) };
		for ( let j = 0; j < 8; j ++ ) poses[ `TurtleTail${ j }` ] = { yaw: Math.sin( time * 1.4 - j * .27 ) * .025 };
	} else if ( id === 'squid' ) {
		for ( let k = 0; k < 12; k ++ ) poses[ `KrakenMantle${ k }` ] = {
			pitch: Math.sin( time * 1.0 - k * .21 ) * .014 - windup * .012,
			roll: Math.cos( time * .7 + k * .25 ) * .008,
		};
		for ( let i = 0; i < 8; i ++ ) {
			const restBearing = Math.PI / 2 + i * TAU / 8;
			const delta = wrap( angle - restBearing );
			const relevance = clamp( ( 1.8 - Math.abs( delta ) ) / 1.25 );
			const reaching = grapple ? windup * relevance : 0;
			for ( let k = 0; k < 24; k ++ ) {
				const t = k / 23;
				const wave = Math.sin( time * ( 1.35 + speed ) - k * 0.26 + i * 0.79 );
				poses[ `Arm${ i }_${ k }` ] = {
					yaw: ( k === 0 ? clamp( delta, -1.55, 1.55 ) * relevance * windup * .24 : 0 ) + wave * ( .026 + .024 * t ),
					pitch: .026 * Math.cos( time * 1.7 + i * .8 - k * .23 ) - reaching * ( k < 4 ? .04 : -.012 ) + attackPulse * relevance * .018,
					roll: .019 * Math.sin( time * 1.3 + i + k * .29 ),
				};
			}
		}
	} else if ( id === 'sea_god' ) {
		// One enormous continuous animal, not a scaled-up triskelion. Motion
		// starts at the skull and travels down 66 real deformation joints.
		const hunt = windup * 0.5 + attackPulse * 0.9;
		for ( let j = 0; j < 66; j ++ ) {
			const t = j / 65;
			poses[ `GodSpine${ j }` ] = {
				yaw: Math.sin( time * ( .62 + speed * .9 ) - t * 9.4 ) * ( .005 + .022 * t ) * ( 1 + hunt * .8 ),
				pitch: Math.sin( time * .42 - t * 6.8 ) * ( .003 + .01 * t ),
				roll: Math.sin( time * .27 + t * 5 ) * .002,
			};
		}
		for ( let j = 0; j < 3; j ++ ) poses[ `GodHead${ j }` ] = {
			yaw: angle * attention * ( .024 - j * .004 ), pitch: - windup * .025 + Math.sin( time * .44 + j ) * .006,
		};
		for ( let j = 0; j < 10; j ++ ) poses[ `GodJaw${ j }` ] = {
			pitch: .016 + ( windup * .11 + attackPulse * .14 ) * ( 1 - j * .045 ),
		};
		for ( const [ label, s ] of [ [ 'L', -1 ], [ 'R', 1 ] ] ) {
			for ( let j = 0; j < 14; j ++ ) poses[ `GodFin${ label }${ j }` ] = {
				pitch: Math.sin( time * 1.05 - j * .2 + s ) * ( .025 + speed * .014 ),
				roll: s * ( windup * .008 + attackPulse * .012 ),
			};
			for ( let j = 0; j < 23; j ++ ) poses[ `GodWhisker${ label }${ j }` ] = {
				yaw: Math.sin( time * 1.1 - j * .26 + s ) * .022,
				pitch: Math.cos( time * .78 - j * .27 + s ) * .018,
			};
			for ( let j = 0; j < 9; j ++ ) poses[ `GodFluke${ label }${ j }` ] = {
				yaw: Math.sin( time * 1.48 - j * .28 ) * ( .024 + speed * .028 ),
			};
		}
	} else if ( id === 'leviathan' ) {
		for ( let j = 0; j < 20; j ++ ) poses[ `HydraSpine${ j }` ] = {
			yaw: Math.sin( time * .69 - j * .24 ) * ( .012 + speed * .009 ),
			pitch: Math.sin( time * .47 - j * .17 ) * .005,
		};
		for ( const [ index, label ] of [ 'C', 'L', 'R' ].entries() ) {
			const offset = ( index - 1 ) * 0.17;
			const track = clamp( angle * attention + offset, -0.95, 0.95 );
			const wave = Math.sin( time * 0.63 + index * 1.6 );
			const stagger = clamp( ( windup * 1.6 - index * 0.16 ) / ( 1 - index * 0.1 ) );
			for ( let j = 0; j < 28; j ++ ) poses[ `${ label }_${ j }` ] = {
				yaw: track * (.006 + .010 * j/27) + Math.sin( time * .63 - j * .22 + index * 1.6 ) * .016,
				pitch: -stagger * (.006 + .010 * j/27) + Math.sin( time * .9 - j * .17 + index ) * .009,
				roll: wave * .006,
			};
			const phase = attackMotion?.biteRemaining > 0 ? attackMotion.biteAge - index * .32 : -1;
			const preOpen = phase < 0 && attackMotion?.biteRemaining > 0
				? clamp( ( phase + .45 ) / .45 ) * .88 : stagger * .8;
			// Independent jaw beats: open during anticipation, bite at contact,
			// linger in the clamp, then release. No time-based random flapping.
			const lunge = phase >= 0 ? clamp( phase / .22 ) * ( 1 - clamp( ( phase - .48 ) / .37 ) ) : 0;
			const jawOpen = phase >= 0 ? 1 - clamp( ( phase - .30 ) / .24 ) : preOpen;
			poses[ `${ label }_Head` ] = { yaw: track * 0.21 + Math.sin( time * 0.8 + index * 2 ) * 0.026,
				pitch: -stagger * 0.10 + lunge * 0.24 };
			for ( let j = 0; j < 4; j ++ ) poses[ `${ label }_Jaw${ j }` ] = {
				pitch: ( .05 + jawOpen * .92 ) * ( .50 - j * .06 ),
			};
		}
	}
	return poses;
}

export function attachTitanSkeleton( asset ) {
	const model = asset?.skeleton;
	if ( ! model ) return false;
	const bones = [];
	for ( let i = 0; i < model.gltf.nodes.length; i ++ ) {
		const name = model.gltf.nodes[ i ].name;
		if ( ! name || name === 'BodyRoot' ) continue;
		bones.push( { name, i, target: { yaw: 0, pitch: 0, roll: 0, stretch: 1 },
			current: { yaw: 0, pitch: 0, roll: 0, stretch: 1 },
			q: new Quaternion(), rest: new Quaternion( ...model.rest[ i ].r ) } );
	}
	const euler = new Euler( 0, 0, 0, 'XYZ' );
	asset.ikPose = new Map();
	model.poseModifier = ( local, rest ) => {
		for ( const bone of bones ) {
			const a = bone.current;
			if ( Math.abs( a.yaw ) + Math.abs( a.pitch ) + Math.abs( a.roll ) + Math.abs( a.stretch - 1 ) < 0.0001 ) continue;
			euler.set( a.pitch, a.yaw, a.roll );
			bone.q.setFromEuler( euler ).premultiply( bone.rest );
			local[ bone.i ].r.set( [ bone.q.x, bone.q.y, bone.q.z, bone.q.w ] );
			if ( a.stretch !== 1 ) for ( let j = 0; j < 3; j ++ ) local[ bone.i ].t[ j ] = rest[ bone.i ].t[ j ] * a.stretch;
		}
		// V22: skeletal IK overrides *only orientation*. Translating a rigged
		// joint would stretch both the skeleton and its bound PBR surface.
		for ( const [ i, pose ] of asset.ikPose ) {
			local[ i ].r.set( pose.r );
		}
	};
	asset.boneControls = bones;
	if ( model.gltf.nodes.some( n => n.name === 'Arm0_0' ) ) prepareTentacleIK( asset );
	if ( model.gltf.nodes.some( n => n.name === 'L_Head' ) ) prepareHydraIK( asset );
	return true;
}

const getPosition = ( matrices, id ) => new Vector3( matrices[ id * 16 + 12 ], matrices[ id * 16 + 13 ], matrices[ id * 16 + 14 ] );
function prepareChain( model, names ) {
	const indices = names.map( name => model.gltf.nodes.findIndex( n => n.name === name ) );
	if ( indices.some( n => n < 0 ) ) return null;
	const heads = indices.map( n => getPosition( model.world, n ) );
	const last = heads.at( -1 ).clone().add( heads.at( -1 ).clone().sub( heads.at( -2 ) ) );
	const parentIndex = model.parent[ indices[ 0 ] ];
	const bindParent = parentIndex >= 0 ? new Matrix4().fromArray( model.world, parentIndex * 16 ) : new Matrix4();
	const lengths = heads.map( ( p, k ) => p.distanceTo( k + 1 < heads.length ? heads[ k + 1 ] : last ) );
	const tipLocal = last.clone().applyMatrix4( new Matrix4().fromArray( model.world, indices.at( -1 ) * 16 ).invert() );
	return {
		indices, rest: [ ...heads, last ],
		tipLocal, actualTip: new Vector3(), actualTipWorld: new Vector3(), socketWorld: new Vector3(),
		contactError: Infinity, contactStrength: 0, latched: false, targetRank: -1,
		bindRotations: indices.map( n => new Quaternion().setFromRotationMatrix( new Matrix4().fromArray( model.world, n * 16 ) ) ),
		parentIndex, bindParent, invBindParent: bindParent.clone().invert(),
		lengths, totalLength: lengths.reduce( ( a, b ) => a + b, 0 ),
		activity: 0, tip: null, initialized: false, endError: Infinity,
		curve: Array.from( { length: indices.length + 1 }, () => new Vector3() ),
		movingRest: Array.from( { length: indices.length + 1 }, () => new Vector3() ),
		ikCache: indices.map( () => ( { r: new Float32Array( 4 ) } ) ),
		// Reuse expensive math objects per creature; never allocate matrix stacks
		// on every frame of a prolonged grapple or three-headed boss fight.
		work: { delta: new Vector3(), aim: new Vector3(), parent: new Matrix4(), tipMatrix: new Matrix4(),
			parentDelta: new Matrix4(), ancestorQ: new Quaternion(), ancestorWorldQ: new Quaternion(),
			t: new Vector3(), s: new Vector3(),
			restAxis: new Vector3(), destAxis: new Vector3(), align: new Quaternion(),
			globalRot: new Quaternion(), localQ: new Quaternion(), bindQ: new Quaternion(),
			point: new Vector3(), previousRoot: new Vector3(), pole: new Vector3() },
	};
}

// Sample the *actual deformed bone* after the skinning pose has been evaluated.
// A target that merely looks close along a mathematical spline cannot latch.
function actualEffector( asset, chain ) {
	const last = chain.indices.at( -1 );
	chain.work.tipMatrix.fromArray( asset.skeleton.world, last * 16 );
	chain.actualTip.copy( chain.tipLocal ).applyMatrix4( chain.work.tipMatrix );
	chain.actualTipWorld.copy( chain.actualTip );
	asset.root.localToWorld( chain.actualTipWorld );
	return chain.actualTipWorld;
}

function attackSequence( asset, kind, pulse, dt ) {
	if ( kind === 'grapple' && pulse > .72 && ( asset.lastGrapplePulse || 0 ) <= .72 ) {
		asset.grappleRemaining = 3.15;
		asset.grappleAge = 0;
	}
	if ( kind === 'triple_bite' && pulse > .72 && ( asset.lastBitePulse || 0 ) <= .72 ) {
		asset.biteRemaining = 2.25;
		asset.biteAge = 0;
		if ( asset.hydraHeads ) for ( const h of asset.hydraHeads ) h.biteLanded = false;
	}
	asset.lastGrapplePulse = kind === 'grapple' ? pulse : 0;
	asset.lastBitePulse = kind === 'triple_bite' ? pulse : 0;
	if ( asset.grappleRemaining > 0 ) {
		asset.grappleRemaining = Math.max( 0, asset.grappleRemaining - dt );
		asset.grappleAge = ( asset.grappleAge || 0 ) + dt;
	}
	if ( asset.biteRemaining > 0 ) {
		asset.biteRemaining = Math.max( 0, asset.biteRemaining - dt );
		asset.biteAge = ( asset.biteAge || 0 ) + dt;
	}
}
function prepareTentacleIK( asset ) {
	const model = asset.skeleton;
	asset.tentacles = [];
	for ( let arm = 0; arm < 8; arm ++ ) {
		const names = model.gltf.nodes.map( n => n.name ).filter( n => new RegExp( `^Arm${ arm }_\\d+$` ).test( n ) )
			.sort( ( a, b ) => Number( a.split( '_' )[ 1 ] ) - Number( b.split( '_' )[ 1 ] ) );
		const chain = prepareChain( model, names );
		if ( chain ) chain.armId = arm;
		if ( chain ) asset.tentacles.push( chain );
	}
}

function prepareHydraIK( asset ) {
	const model = asset.skeleton;
	asset.hydraHeads = [ 'C', 'L', 'R' ].map( label => {
		const names = model.gltf.nodes.map( n => n.name ).filter( n => new RegExp( `^${ label }_\\d+$` ).test( n ) )
			.sort( ( a, b ) => Number( a.split( '_' )[ 1 ] ) - Number( b.split( '_' )[ 1 ] ) );
		return prepareChain( model, [ ...names, `${ label }_Head` ] );
	} ).filter( Boolean );
}

// Length-preserving FABRIK from Aristidou & Lasenby (2011), followed by an
// orientation-only FK reconstruction. Unlike V21, no joint may translate to
// an arbitrary drawn spline. The actual skinned surface stays attached to
// fixed-length limb segments, even when the ship is outside reach.
function solveJointChain( asset, chain, aim, request, dt, lift = 0.6, time = 0, curl = 0 ) {
	chain.activity = smooth( chain.activity, request, dt, 5.2 );
	if ( chain.activity <= 0.005 ) return;
	const N = chain.indices.length;
	const w = chain.work;
	const parentWorld = w.parent.copy( chain.bindParent );
	if ( chain.parentIndex >= 0 ) parentWorld.fromArray( asset.skeleton.world, chain.parentIndex * 16 );
	w.parentDelta.multiplyMatrices( parentWorld, chain.invBindParent );
	w.parentDelta.decompose( w.t, w.ancestorQ, w.s );
	for ( let k = 0; k <= N; k ++ ) chain.movingRest[ k ].copy( chain.rest[ k ] ).applyMatrix4( w.parentDelta );
	const start = chain.movingRest[ 0 ];
	const delta = w.delta.copy( aim ).sub( start );
	const maxReach = chain.totalLength * 0.985;
	const dist = delta.length();
	const reachTarget = w.aim.copy( start ).addScaledVector( delta, Math.min( 1, maxReach / Math.max( dist, 0.001 ) ) );
	if ( ! chain.tip ) chain.tip = chain.movingRest[ N ].clone();
	chain.tip.lerp( reachTarget, 1 - Math.exp( -Math.max( 0, dt ) * 7.5 ) );
	const goal = w.point.copy( chain.movingRest[ N ] ).lerp( chain.tip, chain.activity );
	if ( ! chain.initialized ) {
		for ( let k = 0; k <= N; k ++ ) chain.curve[ k ].copy( chain.movingRest[ k ] );
		chain.initialized = true;
	} else {
		const displacement = w.delta.subVectors( start, chain.curve[ 0 ] );
		for ( let k = 0; k <= N; k ++ ) chain.curve[ k ].add( displacement );
	}
	// Pull middle joints gently toward a raised, curled guide. This gives the
	// solver enough bend to fold a long arm toward a nearby rail rather than
	// remaining trapped in a perfectly straight FABRIK singularity.
	const guideBlend = 1 - Math.exp( -Math.max( dt, 0 ) * 4.0 );
	for ( let k = 1; k < N; k ++ ) {
		const t = k / N, flex = Math.sin( t * Math.PI ) * chain.activity;
		w.pole.copy( start ).lerp( goal, t );
		w.pole.y += flex * lift;
		w.pole.x += flex * curl * Math.sin( time * 1.3 - t * 4.2 + ( chain.armId || 0 ) );
		w.pole.z += flex * curl * Math.cos( time * .9 - t * 2.1 + ( chain.armId || 0 ) );
		chain.curve[ k ].lerp( w.pole, guideBlend );
	}
	for ( let iteration = 0; iteration < 7; iteration ++ ) {
		chain.curve[ N ].copy( goal );
		for ( let k = N - 1; k >= 0; k -- ) {
			const direction = w.delta.subVectors( chain.curve[ k ], chain.curve[ k + 1 ] );
			if ( direction.lengthSq() < 1e-9 ) direction.subVectors( chain.movingRest[ k ], chain.movingRest[ k + 1 ] );
			chain.curve[ k ].copy( chain.curve[ k + 1 ] ).addScaledVector( direction.normalize(), chain.lengths[ k ] );
		}
		chain.curve[ 0 ].copy( start );
		for ( let k = 0; k < N; k ++ ) {
			const direction = w.delta.subVectors( chain.curve[ k + 1 ], chain.curve[ k ] );
			if ( direction.lengthSq() < 1e-9 ) direction.subVectors( chain.movingRest[ k + 1 ], chain.movingRest[ k ] );
			chain.curve[ k + 1 ].copy( chain.curve[ k ] ).addScaledVector( direction.normalize(), chain.lengths[ k ] );
		}
		if ( chain.curve[ N ].distanceToSquared( goal ) < 0.0008 ) break;
	}
	chain.endError = chain.curve[ N ].distanceTo( aim );
	// For every segment, solve its *rotation* against the bind axis, and
	// recover the local rotation from the immediately preceding world rotation.
	// The GLB's rest translations are kept intact by the pose modifier.
	parentWorld.decompose( w.t, w.ancestorWorldQ, w.s );
	for ( let k = 0; k < N; k ++ ) {
		w.restAxis.subVectors( chain.movingRest[ k + 1 ], chain.movingRest[ k ] ).normalize();
		w.destAxis.subVectors( chain.curve[ k + 1 ], chain.curve[ k ] ).normalize();
		w.align.setFromUnitVectors( w.restAxis, w.destAxis );
		w.bindQ.multiplyQuaternions( w.ancestorQ, chain.bindRotations[ k ] );
		w.globalRot.multiplyQuaternions( w.align, w.bindQ ).normalize();
		w.localQ.copy( w.ancestorWorldQ ).invert().multiply( w.globalRot ).normalize();
		const output = chain.ikCache[ k ];
		output.r.set( [ w.localQ.x, w.localQ.y, w.localQ.z, w.localQ.w ] );
		asset.ikPose.set( chain.indices[ k ], output );
		w.ancestorWorldQ.copy( w.globalRot );
	}
}

// All eight high-density tentacles articulate throughout the encounter.
// During grapples the nearest six pursue separately chosen hull hardpoints;
// the other two execute free-swinging flanking/curling guard gestures.
function solveTentacleContact( asset, boss, captain, time, dt, pulse, kind, ship = null ) {
	const arms = asset.tentacles;
	if ( ! arms ) return;
	asset.ikPose.clear();
	const brain = boss.brain;
	const winding = brain.state === 'windup' && brain.attack?.kind === 'grapple'
		? clamp( 1 - brain.windup / Math.max( brain.attack.windup, 0.1 ) ) : 0;
	const grabbing = clamp( ( asset.grappleRemaining || 0 ) / 0.48 );
	const attackWeight = Math.max( winding, grabbing );
	const target = asset.root.worldToLocal( new Vector3( captain.x, captain.y + 0.8, captain.z ) );
	const ranked = arms.map( ( arm, i ) => ( { arm, i, d: arm.rest[ 0 ].distanceTo( target ) } ) ).sort( ( a, b ) => a.d - b.d );
	const attackOrder=new Map(),usedRanks=new Set();
	for(const {arm,i} of ranked)if(arm.latched&&arm.targetRank>=0&&arm.targetRank<6&&!usedRanks.has(arm.targetRank)){attackOrder.set(i,arm.targetRank);usedRanks.add(arm.targetRank);}
	for(const {i} of ranked)if(!attackOrder.has(i)){let rank=0;while(usedRanks.has(rank))rank++;attackOrder.set(i,rank);usedRanks.add(rank);}
	const dims = ship?.model?.dimensions;
	const beam = Math.max( 2.5, dims?.beam ?? 5.2 );
	const length = Math.max( 6, dims?.length ?? 11 );
	const hullSocket = asset.hullSocket ||= new Vector3();
	const engaged = ['windup', 'chase', 'charge', 'alert'].includes( brain.state ) || grabbing > 0;
	for ( let i = 0; i < arms.length; i ++ ) {
		const arm = arms[ i ];arm.cutRemaining=Math.max(0,(arm.cutRemaining||0)-dt);
		const rank = attackOrder.get( i );
		arm.socketRank = rank;
		const canReach = target.distanceTo( arm.rest[ 0 ] ) < arm.totalLength * 1.15;
		const flank = rank >= 6;
		const reach = engaged && canReach && ! flank && !arm.cutRemaining ? attackWeight : 0;
		const request = Math.max( .28 + .13 * Math.sin( time * 1.05 + i ), reach );
		const aim = target.clone();
		arm.reachingHull = !! ( ship?.toWorld && ! flank && canReach && attackWeight > .18 && !arm.cutRemaining );
		if ( flank || ! canReach || arm.cutRemaining ) {
			// Independently curl in open water when too far to contact the hull.
			aim.copy( arm.rest.at( -1 ) );
			aim.x += Math.sin( time * 1.17 + i * 1.7 ) * 1.4;
			aim.z += Math.cos( time * .81 + i * 1.2 ) * 1.1;
			aim.y += Math.sin( time * 1.6 + i ) * .55;
		} else {
			// Track actual, orientation-correct ship hardpoints. They follow
			// the vessel's yaw, rolling and pitching, not a fixed global circle.
			if ( ship?.toWorld ) {
				const row = Math.floor( rank / 2 );
				const side = rank % 2 === 0 ? -1 : 1;
				hullSocket.set( side * beam * HULL_X[ row ], HULL_Y[ row ], length * HULL_Z[ row ] );
				ship.toWorld( hullSocket, arm.socketWorld );
				aim.copy( arm.socketWorld );
				asset.root.worldToLocal( aim );
			} else {
				aim.x += Math.sin( rank * TAU / 6 ) * 1.3;
				aim.z += Math.cos( rank * TAU / 6 ) * 1.75;
			}
			// During a hull latch the endpoint stays precisely on the boat's
			// animated socket, including its roll and pitch. No wobble offsets.
		}
		solveJointChain( asset, arm, aim, request, dt, .5 + 1.2 * attackWeight, time, .2 + .34 * attackWeight );
	}
}

// All three separately rigged heads track the boat, with staggered acquire,
// extension and biting; the central head attacks first, flanks follow.
function solveHydraBites( asset, boss, captain, time, dt, pulse, kind, ship = null ) {
	if ( ! asset.hydraHeads ) return;
	asset.ikPose.clear();
	const brain = boss.brain;
	const winding = brain.state === 'windup' && brain.attack?.kind === 'triple_bite'
		? clamp( 1 - brain.windup / Math.max( brain.attack.windup, 0.1 ) ) : 0;
	const recoil = clamp( ( asset.biteRemaining || 0 ) / 0.40 );
	const base = Math.max( winding, recoil );
	const target = asset.root.worldToLocal( new Vector3( captain.x, captain.y + 1.2, captain.z ) );
	const beam = Math.max( 2.5, ship?.model?.dimensions?.beam ?? 5.2 );
	const length = Math.max( 6, ship?.model?.dimensions?.length ?? 11 );
	const hullSocket = asset.hullSocket ||= new Vector3();
	for ( let i = 0; i < asset.hydraHeads.length; i ++ ) {
		const head = asset.hydraHeads[ i ];
		const phase = ( asset.biteRemaining || 0 ) > 0 ? ( asset.biteAge || 0 ) - i * .32 : -1;
		const hitPoint = target.clone().add( new Vector3( ( i - 1 ) * 1.35, - i * 0.3, i * 0.4 ) );
		if ( ship?.toWorld ) {
			const hullX = i === 0 ? 0 : ( i === 1 ? -1 : 1 ) * beam * .43;
			const hullZ = i === 0 ? length * .28 : i === 1 ? 0 : -length * .26;
			ship.toWorld( hullSocket.set( hullX, 1.25, hullZ ), head.socketWorld );
			hitPoint.copy( head.socketWorld );
			asset.root.worldToLocal( hitPoint );
		}
		const request = clamp( winding * 1.2 - i * .06 + ( phase >= - .15 && phase < 1.3 ? recoil : 0 ) ) *
			( head.rest[ 0 ].distanceTo( hitPoint ) < head.totalLength * 1.35 ? 1 : 0 );
		head.reachingHull = !! ( ship?.toWorld && request > .12 );
		solveJointChain( asset, head, hitPoint, request, dt, 1.3 + 0.4 * i, time, .18 );
	}
}

function realHullTouch(worldPoint,ship,radius){
 if(!ship?.model?.collisionWorld)return null;
 const p=worldPoint.clone().sub(ship.position).applyQuaternion(ship.quaternion.clone().invert());
 const hit=ship.model.collisionWorld.sphereContact(p,radius);if(!hit)return null;
 return ship.toWorld(new Vector3(hit.point.x,hit.point.y,hit.point.z),new Vector3());
}
export function updateTitanSkeleton( asset, boss, captain, time, dt, pulse = 0, kind = '', ship = null ) {
	if ( ! asset?.skeleton || ! asset.boneControls ) return;
	attackSequence( asset, kind, pulse, dt );
	const poses = skeletonTargets( boss.id, boss, captain, time, pulse, kind, asset );
	for ( const bone of asset.boneControls ) {
		const wanted = poses[ bone.name ] || {};
		for ( const key of [ 'yaw', 'pitch', 'roll', 'stretch' ] ) {
			const target = wanted[ key ] ?? ( key === 'stretch' ? 1 : 0 );
			bone.current[ key ] = smooth( bone.current[ key ], target, dt, boss.brain.state === 'charge' ? 12 : 6.5 );
		}
	}
	if ( boss.id === 'squid' ) solveTentacleContact( asset, boss, captain, time, dt, pulse, kind, ship );
	if ( boss.id === 'leviathan' ) solveHydraBites( asset, boss, captain, time, dt, pulse, kind, ship );
	asset.skeleton.update( dt );
	asset.contactEvents ||= [];
	asset.contactEvents.length = 0;
	if ( boss.id === 'squid' && asset.tentacles ) {
		let gripping = 0, pull = 0;
		for ( const arm of asset.tentacles ) {
			actualEffector( asset, arm );
			arm.contactError = arm.actualTipWorld.distanceTo( arm.socketWorld );
			const eligible = arm.reachingHull && ( asset.grappleRemaining || 0 ) > .20;
			const actualContact=realHullTouch(arm.actualTipWorld,ship,.65);
			const contact = eligible && (ship?.model?.collisionWorld ? !!actualContact : arm.contactError < 1.8);
			if ( contact && ! arm.latched ) {
				arm.latched = true;
				arm.targetRank = arm.socketRank;
				asset.contactEvents.push( { type: 'grip', position: actualContact||arm.socketWorld.clone(), strength: 0.9,boneId:'Arm'+arm.armId } );
			}
			if ( ! eligible || arm.contactError > 3.5 || ship?.model?.collisionWorld&&!actualContact ) { arm.latched = false; arm.targetRank = -1; }
			arm.contactStrength = smooth( arm.contactStrength, arm.latched ? 1 : 0, dt, arm.latched ? 6 : 3 );
			if ( arm.latched ) { gripping ++; pull += arm.contactStrength; }
		}
		asset.gripCount = gripping;
		asset.gripStrength = pull;
	}
	if ( boss.id === 'leviathan' && asset.hydraHeads ) {
		for ( let i = 0; i < asset.hydraHeads.length; i ++ ) {
			const head = asset.hydraHeads[ i ];
			actualEffector( asset, head );
			head.contactError = head.actualTipWorld.distanceTo( head.socketWorld );
			const age = ( asset.biteAge || 0 ) - i * .32;
			if ( ! head.biteLanded && head.reachingHull && ( asset.biteRemaining || 0 ) > 0 &&
				age >= .30 && age < .77 && (ship?.model?.collisionWorld ? !!realHullTouch(head.actualTipWorld,ship,1.1) : head.contactError < 3.1) ) {
				head.biteLanded = true;
				asset.contactEvents.push( { type: 'bite', position: realHullTouch(head.actualTipWorld,ship,1.1)||head.socketWorld.clone(), strength: 1.4, head: i,boneId:'Head'+i } );
			}
		}
	}
}
